package com.farm2market.controller;
import com.farm2market.dto.*; import com.farm2market.entity.*; import com.farm2market.repository.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController {final ProductRepository products;final UserRepository users; ProductController(ProductRepository p,UserRepository u){products=p;users=u;} @GetMapping public Map<String,Object> all(){return Map.of("success",true,"data",products.findByActiveTrue());} @GetMapping("/{id}") public Product one(@PathVariable Long id){return products.findById(id).orElseThrow(()->new RuntimeException("Product not found"));} @GetMapping("/search") public Map<String,Object> search(@RequestParam String keyword){return Map.of("success",true,"data",products.findByNameContainingIgnoreCaseAndActiveTrue(keyword));} @GetMapping("/category/{category}") public Map<String,Object> cat(@PathVariable Category category){return Map.of("success",true,"data",products.findByCategoryAndActiveTrue(category));} @PostMapping public Product add(@Valid @RequestBody ProductRequest x,@RequestParam String farmerEmail){User f=users.findByEmail(farmerEmail).orElseThrow();Product p=new Product();p.setFarmer(f);copy(p,x);return products.save(p);} @PutMapping("/{id}") public Product edit(@PathVariable Long id,@Valid @RequestBody ProductRequest x){Product p=one(id);copy(p,x);return products.save(p);} @DeleteMapping("/{id}") public Map<String,Object> delete(@PathVariable Long id){Product p=one(id);p.setActive(false);products.save(p);return Map.of("success",true,"message","Product removed");} void copy(Product p,ProductRequest x){p.setName(x.name());p.setCategory(x.category());p.setDescription(x.description());p.setPricePerKg(x.pricePerKg());p.setAvailableQuantity(x.availableQuantity());p.setUnit(x.unit()==null?"kg":x.unit());p.setMinimumOrderQuantity(x.minimumOrderQuantity());p.setQualityGrade(x.qualityGrade());p.setLocation(x.location());p.setImageUrl(x.imageUrl());}}
